#include "stop_cases.inc"
#include <esp_timer.h>
namespace {
void report(uint8_t mask){uint8_t data=mask;check(hid_backend::receiveLockReport(1,&data,1,hid_backend::lockSession()),"actual accepted OUT callback adapter");}
void feed(bool badCrc=false,bool badLength=false,bool noise=false){
 std::vector<uint8_t> v={0,0x45,0x44,0x52,0x31,uint8_t(badLength?18:17)};for(char c:std::string(led_return::Message))v.push_back(c);if(noise)v[6]='X';auto crc=led_return::crc16(v.data()+5,v.size()-5);v.push_back(uint8_t(crc>>8));v.push_back(uint8_t(crc)^(badCrc?1:0));uint8_t clock=0;report(0);
 for(auto byte:v)for(int i=7;i>=0;--i){led_mock::nowUs+=50000;uint8_t mask=clock|((byte>>i)&1);report(mask);report(mask);clock^=2;report(clock|((byte>>i)&1));led_return::service(led_mock::nowUs);}
}
}
int main(int argc,char**argv){if(argc!=2)return 2;if(argv[1][0]!='L')return historical_stop_main(argc,argv);try{
 mscMock::reset();mock::reset();setup();check(startupControlledReady,"controlled setup");check(route_u::bindOwner(),"owner");lower::reset();led_mock::nowUs=0;std::string id=argv[1];auto r=req();
 if(id=="L01"){handleLedTest(&r,0);check(r.code==200&&r.response.indexOf("\"feedback\":\"unknown\"")>=0&&r.response.indexOf("\"caps\":null")>=0,"unknown not false/off");uint8_t mask=0;report(mask);handleLedTest(&r,0);check(r.response.indexOf("\"observed\":true")>=0&&r.response.indexOf("\"caps\":false")>=0,"actual all-off report observed");}
 else if(id=="L02"){check(led_return::start(0),"explicit arm");feed();auto s=led_return::snapshot(led_mock::nowUs);check(s.state==led_return::State::Complete&&s.integrity&&std::string(s.text)==led_return::Message,"byte exact fixed message with repeated report states");handleLedTest(&r,4);check(r.code==200&&r.response==led_return::Message,"authenticated RAM download");}
 else if(id=="L03"){uint8_t x=0;auto session=hid_backend::lockSession();check(!hid_backend::receiveLockReport(0,&x,1,session)&&!hid_backend::receiveLockReport(2,&x,1,session)&&!hid_backend::receiveLockReport(1,nullptr,1,session)&&!hid_backend::receiveLockReport(1,&x,0,session)&&!hid_backend::receiveLockReport(1,&x,2,session),"ID and bounds rejected");x=0x80;check(!hid_backend::receiveLockReport(1,&x,1,session),"reserved bit");check(led_return::snapshot(0).rejected==6,"invalid report counter");}
 else if(id=="L04"){led_return::start(0);led_return::service(led_return::TimeoutUs);check(led_return::snapshot(led_return::TimeoutUs).state==led_return::State::Timeout,"finite timeout equality");}
 else if(id=="L05"||id=="L06"||id=="L07"){led_return::start(0);feed(id=="L05",id=="L06",id=="L07");auto s=led_return::snapshot(led_mock::nowUs);check(s.state==led_return::State::InvalidFrame&&!s.integrity&&s.text[0]==0,"CRC/length/nonfixed text fail closed");}
 else if(id=="L08"){led_return::start(0);for(int i=0;i<65;++i)report(i&3);auto s=led_return::snapshot(0);check(s.state==led_return::State::Overflow&&s.overflow==1&&!s.integrity,"overflow abort not silently dropped");}
 else if(id=="L09"){report(3);led_return::start(0);auto old=hid_backend::lockSession();hid_backend::invalidateLockState();uint8_t x=3;check(!hid_backend::receiveLockReport(1,&x,1,old),"stale session rejected");auto s=led_return::snapshot(0);check(s.state==led_return::State::Disconnected&&!s.observed&&!s.connected&&s.disconnected,"disconnect/invalidation abort");}
 else if(id=="L10"){report(7);auto s=led_return::snapshot(led_return::StaleUs+1);check(s.observed&&s.stale&&s.mask==7,"stale separate from observed mask");}
 else if(id=="L11"){feed();check(led_return::snapshot(led_mock::nowUs).state==led_return::State::Idle,"unarmed does not decode");}
 else if(id=="L12"){led_return::start(0);led_return::stop();check(led_return::snapshot(0).state==led_return::State::Stopped,"separate stop receiving");led_return::clear();check(led_return::snapshot(0).state==led_return::State::Idle,"clear only receiver state");}
 else if(id=="L13"){r.headers.clear();for(int i=0;i<5;++i){handleLedTest(&r,i);check(r.code==401,"all receiver APIs require live auth");}check(led_return::snapshot(0).state==led_return::State::Idle&&lower::count==0,"no unauthenticated arm or output");}
 else if(id=="L14"){handleLedTest(&r,1);check(r.code==200,"explicit authenticated arm");handleLedTest(&r,1);check(r.code==409,"duplicate arm refused");handleLedTest(&r,4);check(r.code==409,"unverified download refused");handleStop(&r);check(led_return::snapshot(0).state==led_return::State::Receiving,"STOP script independent from receiver");handleLedTest(&r,2);check(r.code==200,"independent authenticated receive stop");}
 else if(id=="L15"){led_return::start(100);led_return::service(99);check(led_return::snapshot(100).state==led_return::State::ClockError,"clock regression aborts");}
 else if(id=="L16"){auto before=led_return::snapshot(0).reports;auto session=hid_backend::lockSession();std::thread a([&]{for(int i=0;i<500;++i)led_return::observe(0,session,0);});std::thread b([&]{for(int i=0;i<500;++i)led_return::observe(1,session,0);});a.join();b.join();check(led_return::snapshot(0).reports==before+1000,"concurrent ingress fixed synchronized accounting");}
 else if(id=="L17"){led_return::start(0);put("/x.txt","DELAY 500\nSTRING BAD\n");start();report(0);loop();handleStop(&r);done();check(route_u::status().reason==route_u::Reason::Cancelled&&presses().empty(),"execution cancellation preserved while receiving");check(led_return::snapshot(0).state==led_return::State::Receiving,"receiver independent lifetime");}
 else if(id=="L18"){r.path="/index.html";handleStatic(&r);check(r.response.indexOf("Stop receiving")>=0&&r.response.indexOf("RAM only")>=0,"served finite receiver controls");r.path="/index.js";handleStatic(&r);check(r.response.indexOf("out.textContent=text")>=0&&r.response.indexOf("/led-test/data")>=0,"safe text render and authenticated data path");}
 else if(id=="L19"){uint8_t body[18]={17};memcpy(body+1,led_return::Message,17);check(led_return::crc16(body,18)==0xd6cc,"independent Python crc_hqx reference vector");}
 else check(false,"unknown case");std::cout<<"PASS "<<id<<" ("<<assertions<<" assertions)\n";return 0;
 }catch(const std::exception&e){std::cerr<<"FAIL "<<argv[1]<<": "<<e.what()<<" ("<<assertions<<")\n";return 1;}}
